import sys
from collections import defaultdict, deque
import heapq

def find_maximum_fee(N, P, X, Y, partnerships, swerc_banks):
    # Create a graph representation of partnerships
    graph = defaultdict(list)
    for a, b, c in partnerships:
        graph[a].append((b, c))
        graph[b].append((a, c))

    # Check if there's a direct path from X to Y using only SWERC banks
    def is_direct_path():
        visited = set()
        queue = deque([X])
        while queue:
            node = queue.popleft()
            if node == Y:
                return True
            if node in visited:
                continue
            visited.add(node)
            for neighbor, _ in graph[node]:
                if neighbor in swerc_banks:
                    queue.append(neighbor)
        return False

    if is_direct_path():
        return "Infinity"

    # Use Dijkstra's algorithm to find the cheapest path without any SWERC fee
    def dijkstra(source, target):
        heap = [(0, source)]
        min_cost = {source: 0}
        while heap:
            current_cost, node = heapq.heappop(heap)
            if node == target:
                return current_cost
            for neighbor, fee in graph[node]:
                new_cost = current_cost + fee
                if neighbor not in min_cost or new_cost < min_cost[neighbor]:
                    min_cost[neighbor] = new_cost
                    heapq.heappush(heap, (new_cost, neighbor))
        return float('inf')

    # Calculate the cheapest cost without any SWERC fee
    cheapest_cost = dijkstra(X, Y)

    # Perform a binary search to find the maximum fee
    left, right = 1, 1000000000
    result = "Impossible"
    while left <= right:
        mid = (left + right) // 2
        max_cost_with_fee = cheapest_cost + mid

        # Check if there's a path from X to Y with the maximum allowed cost
        def is_path_with_max_fee():
            heap = [(0, X)]
            min_cost = {X: 0}
            while heap:
                current_cost, node = heapq.heappop(heap)
                if node == Y:
                    return current_cost <= max_cost_with_fee
                if node in visited:
                    continue
                visited.add(node)
                for neighbor, fee in graph[node]:
                    new_cost = current_cost + fee
                    if neighbor in swerc_banks:
                        new_cost += mid  # Add the SWERC fee
                    if neighbor not in min_cost or new_cost < min_cost[neighbor]:
                        min_cost[neighbor] = new_cost
                        heapq.heappush(heap, (new_cost, neighbor))
            return False

        visited = set()
        if is_path_with_max_fee():
            result = mid
            left = mid + 1
        else:
            right = mid - 1

    return result

